1 2 3 4 5 6 7 8 &lt;script type=&#34;text/javascript&#34;&gt; var geoc = new BMap.Geocoder(); geoc.getLocation(new BMap.Point(120.3066572944592,31.56715494761835), function(rs){ var addComp = rs.addressComponents; var site = addComp.province + addComp.city + addComp.district + addComp.street + addComp.streetNumber; console.log(site); }); &lt;/script&gt;
